//! The "scaffolded, not implemented" error channel for `com-amazonaws-guardduty-guarddutyapiservice`.
//!
//! @generated by the emulator core scaffold op-stub generator.
//!
//! Every generated operation stub returns [`Scaffolded::not_implemented`], which the
//! framework renders as a protocol-correct **HTTP 501 `NotImplemented`**. Do not change
//! a stub to return a success value: a client, and any check that only asserts the call
//! succeeded, cannot tell an empty success from a real implementation. Implement the
//! operation, or leave the 501.
//!
//! ## The error type
//!
//! A stub's error type is `Scaffolded<{Op}ErrorModeled>` — the model's own error enum
//! plus the `NotImplemented` variant. Do not try to add `NotImplemented` to the
//! `#[operation_error]` enum directly; it accepts only variants the model declares.
//!
//! ## Implementing an operation
//!
//! Replace the `Err(..)` in the handler body with real behaviour. Each stub emits a
//! CONCRETE `impl From<{Op}ErrorModeled> for {Op}Error` beside its
//! alias, so `?` works through the wrapper and a modeled failure needs no ceremony:
//!
//! ```ignore
//! return Err(GetThingErrorModeled::ResourceNotFound(
//!     ResourceNotFound { message: Some("no such thing".into()) },
//! )
//! .into());
//! ```
//!
//! That impl is emitted per operation, not once for all of them — keep it that way if
//! you edit a stub.
//!
//! ## Once the operation is implemented
//!
//! Keep the `#[operation_error]` enum, the alias and the `From` impl.
//!
//! An implemented operation stops needing the 501, but the wrapper is also the only
//! place it can return an error its own model does not declare — `validation` above,
//! for a service whose model carries no client-input error. Delete the wrapper and the
//! handler has no way to refuse a bad request at all.

use aws_smithy_schema::serde::{SerdeError, SerializableStruct, ShapeSerializer};
use aws_smithy_schema::{Schema, ShapeId, ShapeType};
use smithy_server_runtime::OperationError;

/// The `message` member of the synthetic `NotImplemented` error shape.
///
/// `with_xml_name("Message")` matches the casing the restXml / awsQuery error
/// envelopes use, so the same value renders correctly on the XML protocols and as
/// lowercase `message` on the JSON/CBOR ones.
static NOT_IMPLEMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#NotImplemented$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `NotImplemented` error shape.
///
/// Deliberately in the `smithy.framework` namespace: this shape is NOT in any
/// service's model, so it must not collide with a modeled shape. The wire `__type` /
/// `<Code>` comes from [`OperationError::shape_name`] below, not from this schema.
pub static NOT_IMPLEMENTED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#NotImplemented",
        "smithy.framework",
        "NotImplemented",
    ),
    ShapeType::Structure,
    &[&NOT_IMPLEMENTED_MESSAGE],
);

/// The payload of a `NotImplemented` failure: which operation was called, and the
/// fact that it is scaffolded rather than broken.
#[derive(Debug, Clone)]
pub struct NotImplemented {
    pub message: String,
}

impl NotImplemented {
    /// A `NotImplemented` naming `operation`.
    ///
    /// The wording matters: it must read as "not written yet", never as "the emulator
    /// is broken", because that distinction is what a human triaging a failing fixture
    /// needs first.
    pub fn new(operation: &str) -> Self {
        Self {
            message: format!(
                "operation {operation} is scaffolded but not implemented in this emulator"
            ),
        }
    }
}

impl std::fmt::Display for NotImplemented {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NotImplemented: {}", self.message)
    }
}

impl std::error::Error for NotImplemented {}

impl SerializableStruct for NotImplemented {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&NOT_IMPLEMENTED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ValidationException` error shape.
static VALIDATION_EXCEPTION_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ValidationException$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ValidationException` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model, so it must not collide with a modeled one.
/// If THIS service's model declares its own `ValidationException`, prefer that —
/// see [`Scaffolded::validation`].
pub static VALIDATION_EXCEPTION_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ValidationException",
        "smithy.framework",
        "ValidationException",
    ),
    ShapeType::Structure,
    &[&VALIDATION_EXCEPTION_MESSAGE],
);

/// The payload of a `ValidationException`: why the request was refused.
#[derive(Debug, Clone)]
pub struct ValidationException {
    pub message: String,
}

impl ValidationException {
    /// A `ValidationException` carrying `message`.
    ///
    /// Say what was wrong with the request and name the member, the way the
    /// boundary validator does — the caller has to fix the request from this text
    /// alone.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ValidationException {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ValidationException: {}", self.message)
    }
}

impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The error CLASS GuardDuty rejects an unacceptable request input with.
///
/// GuardDuty's model folds every client rejection into the single
/// `BadRequestException` envelope (`httpError` 400, members `message` and `type`,
/// "The error type"), but the service answers with the specific class: the body
/// carries it in BOTH the `__type` discriminator and the exception's own `type`
/// member, so a client switching on the error type can tell an unacceptable input
/// from any other 400. See [`ClassifiedError`].
pub const INVALID_INPUT_EXCEPTION: &str = "InvalidInputException";

/// The modeled error SHAPE every one of this service's client rejections is
/// enveloped in: the only client error bound to its operations
/// (`smithy_query(query="service_info")` lists it among the common errors).
///
/// restJson1 resolves the error shape from the `x-amzn-errortype` header rather
/// than from the body, so that header names the SHAPE while the body's `__type`
/// names the class. The two differ on purpose: an SDK needs the shape to
/// unmarshal the response into, and the client needs the class to switch on.
pub const BAD_REQUEST_EXCEPTION: &str = "BadRequestException";

/// The error CLASS GuardDuty names a request it refuses because work it collides
/// with is already running.
///
/// The service's own server error shape (`httpError` 500,
/// `smithy_query(shape="InternalServerErrorException")`), and a modelled error of
/// the operations that answer it — but the refusal carries the status of a request
/// the service will not perform rather than the shape's own, because nothing
/// failed on the server: see [`Scaffolded::in_progress`].
pub const INTERNAL_SERVER_ERROR_EXCEPTION: &str = "InternalServerErrorException";

/// `message` of a classified rejection, rendered with the `jsonName` the modeled
/// envelope gives it (`smithy_query(shape="BadRequestException")`).
///
/// The shape this and its siblings hang off lives in `smithy.framework`, like
/// [`NOT_IMPLEMENTED_SCHEMA`] above and for the same reason: it carries a member the
/// model does not declare (the header binding below), so it must not claim a modeled
/// shape's id. Nothing depends on that id — the wire names come from the explicit
/// `jsonName`s here and from [`OperationError::shape_name`].
static CLASSIFIED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ClassifiedError$Message",
        "smithy.framework#ClassifiedError",
        "Message",
    ),
    ShapeType::String,
    "Message",
    0,
)
.with_json_name("message")
.with_xml_name("Message");

/// `type` — "The error type" — of a classified rejection.
static CLASSIFIED_TYPE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ClassifiedError$Type",
        "smithy.framework#ClassifiedError",
        "Type",
    ),
    ShapeType::String,
    "Type",
    1,
)
.with_json_name("type")
.with_xml_name("Type");

/// The `x-amzn-errortype` header, bound as a member so it carries the modeled
/// envelope SHAPE rather than the error class.
///
/// The framework writes the error code to this header and then lets an
/// `@httpHeader`-bound member win, which is the seam this uses: without it the
/// header and the body's `__type` would both carry the class, and a restJson1 SDK —
/// which resolves the error shape from the header — would fail to find a shape by
/// that name at all.
static CLASSIFIED_ERROR_TYPE_HEADER: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ClassifiedError$ErrorType",
        "smithy.framework#ClassifiedError",
        "ErrorType",
    ),
    ShapeType::String,
    "ErrorType",
    2,
)
.with_http_header("x-amzn-errortype");

/// Schema for a classified rejection: the modeled envelope's body members, plus the
/// header binding above.
static CLASSIFIED_ERROR_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ClassifiedError",
        "smithy.framework",
        "ClassifiedError",
    ),
    ShapeType::Structure,
    &[
        &CLASSIFIED_MESSAGE,
        &CLASSIFIED_TYPE,
        &CLASSIFIED_ERROR_TYPE_HEADER,
    ],
);

/// A GuardDuty client rejection, carrying the error CLASS the wire names it by.
///
/// The body is the model's own `BadRequestException` — the same members with the
/// same `jsonName`s — with `type` set to the class and the `__type` discriminator
/// carrying it too. The `x-amzn-errortype` header still names the envelope shape,
/// because that is what resolves the error shape on restJson1. Construct it through
/// [`Scaffolded::invalid_input`].
#[derive(Debug, Clone)]
pub struct ClassifiedError {
    /// The error class, written to the body's `__type` and `type`.
    class: &'static str,
    /// The modeled error shape the class is enveloped in, written to
    /// `x-amzn-errortype`.
    envelope: &'static str,
    /// Why the request was refused: built from the request, never from the store.
    message: String,
}

impl ClassifiedError {
    /// A rejection of class `class`, enveloped in `envelope`, carrying `message`.
    ///
    /// The body's `type` is set from `class` rather than taken separately: the two
    /// are the same fact, and a body whose `__type` and `type` disagreed would
    /// describe two different errors at once.
    pub fn new(class: &'static str, envelope: &'static str, message: impl Into<String>) -> Self {
        Self {
            class,
            envelope,
            message: message.into(),
        }
    }

    /// The error class this rejection is named by on the wire.
    pub fn class(&self) -> &'static str {
        self.class
    }
}

impl std::fmt::Display for ClassifiedError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.class, self.message)
    }
}

impl std::error::Error for ClassifiedError {}

impl SerializableStruct for ClassifiedError {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&CLASSIFIED_MESSAGE, self.message.as_str())?;
        s.write_string(&CLASSIFIED_TYPE, self.class)?;
        s.write_string(&CLASSIFIED_ERROR_TYPE_HEADER, self.envelope)?;
        Ok(())
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// A client rejection rendered under GuardDuty's own error class rather than
    /// under the `BadRequestException` envelope the model names. HTTP 400.
    Classified(ClassifiedError),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request as GuardDuty does: HTTP 400 under the
    /// [`INVALID_INPUT_EXCEPTION`] class, in both the body's `__type` and its
    /// `type` member.
    ///
    /// This is the ONLY way this service answers a client rejection. Returning the
    /// modeled `BadRequestException` variant instead names the envelope shape in
    /// `__type` and leaves `type` absent, which is not what the service sends.
    ///
    /// `message` must be built from the REQUEST — the parameter at fault and the
    /// rule it broke — never from the store: GuardDuty does not echo a caller's
    /// resource id or the endpoint's Region back in a rejection.
    pub fn invalid_input(message: impl Into<String>) -> Self {
        Self::Classified(ClassifiedError::new(
            INVALID_INPUT_EXCEPTION,
            BAD_REQUEST_EXCEPTION,
            message,
        ))
    }

    /// Refuse the request as GuardDuty refuses a change to a resource whose own
    /// delete is already running: the status of a request the service will not
    /// perform (400), under the [`INTERNAL_SERVER_ERROR_EXCEPTION`] class.
    ///
    /// The class is the SERVER one on purpose — it is the error code GuardDuty
    /// names this collision by — so it is carried in the body's `__type` and
    /// `type` AND in the `x-amzn-errortype` header that resolves the error shape:
    /// the class is itself a modelled error of the operations that answer it, so
    /// an SDK still unmarshals the response, and a client reading the code alone
    /// tells a collision with work already in flight (retry later) from an
    /// unacceptable parameter (do not retry).
    pub fn in_progress(message: impl Into<String>) -> Self {
        Self::Classified(ClassifiedError::new(
            INTERNAL_SERVER_ERROR_EXCEPTION,
            INTERNAL_SERVER_ERROR_EXCEPTION,
            message,
        ))
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::Classified(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::Classified(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            // The members come from the modeled envelope, so `message` and `type`
            // render with the `jsonName`s the model gives them.
            Self::Classified(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::Classified(_) => &CLASSIFIED_ERROR_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The error CLASS, not the envelope shape: that is what GuardDuty puts
            // in `__type`, and what the body's `type` member repeats.
            Self::Classified(e) => e.class(),
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            // `BadRequestException` carries `httpError` 400
            // (`smithy_query(shape="BadRequestException")`), and the class is one of
            // the rejections it envelopes.
            Self::Classified(_) => 400,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // GuardDuty is restJson1 only (`smithy_query(query="service_info")`), so
            // no awsQuery code applies.
            Self::Classified(_) => None,
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::ValidationException(_) => None,
        }
    }
}
